    /// <summary>
    /// update related fields on field modified
    /// </summary>
    /// <param name = "_fieldId">modified field</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METVendorClaimRegister, Qty):
            case fieldNum(METVendorClaimRegister, UnitClaimAmount):
                this.setClaimAmount();
                break;

            case fieldNum(METVendorClaimRegister, ItemId):
                this.ItemDescription = InventTable::find(this.ItemId).itemName();
                break;
        }
    }

/// <summary>
/// Set claim amount based on Qty and Unit claim price
/// </summary>
public void setClaimAmount()
{
    if(this.ClaimType == METVendorClaimType::StandardCost || this.ClaimType == METVendorClaimType::FreeItemExcise)
    {
        this.ClaimAmount = this.Qty * this.UnitClaimAmount;
    }
}

    /// <summary>
    /// Find the record matching with criteria and return
    /// </summary>
    /// <param name = "_claimRecId">Claim RecId</param>
    /// <param name = "_forUpdate">Indicates whether record to be selected for update</param>
    /// <returns><c>METVendorClaimRegister</c> record buffer</returns>
    public static METVendorClaimRegister find(RefRecId _claimRecId, boolean _forUpdate = false)
    {
        METVendorClaimRegister vendorClaimRegister;

        if(_claimRecId)
        {
            vendorClaimRegister.selectForUpdate(_forUpdate);

            select firstonly vendorClaimRegister
                where vendorClaimRegister.RecId == _claimRecId;
        }

        return vendorClaimRegister;
    }

    /// <summary>
    /// update the claim status for selected record buffer
    /// </summary>
    /// <param name = "_status">Clami status</param>
    public void updateClaimStatus(METVendorClaimStatus _status)
    {
        ttsbegin;

        this.ClaimStatus = _status;
        this.update();

        ttscommit;
    }

    /// <summary>
    /// Check whether unprocessed claim lines exist for processing for specific claim type and site
    /// </summary>
    /// <param name = "_claimType">Claim type</param>
    /// <param name = "_siteId">Site id</param>
    /// <returns>true if lines exists.</returns>
    public static boolean existClaimLinesToProcess(METVendorClaimType _claimType, InventSiteId _siteId)
    {
        METVendorClaimRegister vendorClaimRegister;

        select firstonly RecId 
            from vendorClaimRegister
            where vendorClaimRegister.ClaimType == _claimType
            &&  vendorClaimRegister.ClaimStatus == METVendorClaimStatus::Approved
            &&  vendorClaimRegister.Claimed == NoYes::No
            &&  vendorClaimRegister.SiteId == _siteId;

        return (vendorClaimRegister.RecId != 0);
    }
